<template>
  <section>
    <div class="mb-5"><h1 class="text-h4">Platform Administration</h1><p class="text-medium-emphasis mt-1">Manage platform access, organizers and administrative history.</p></div>
    <v-alert v-if="error" type="error" variant="tonal" class="mb-4">{{ error }}</v-alert>
    <v-tabs v-model="tab" class="mb-4"><v-tab value="overview">Overview</v-tab><v-tab value="users">Users</v-tab><v-tab value="organizers">Organizers</v-tab><v-tab value="audit">Audit history</v-tab></v-tabs>
    <v-window v-model="tab">
      <v-window-item value="overview">
        <v-progress-linear v-if="busy" indeterminate />
        <v-row v-else><v-col v-for="metric in metrics" :key="metric.label" cols="12" sm="6" md="3"><v-card rounded="lg"><v-card-text><div class="text-medium-emphasis">{{ metric.label }}</div><div class="text-h4 mt-2">{{ metric.value }}</div></v-card-text></v-card></v-col></v-row>
        <v-card class="mt-5" rounded="lg"><v-card-title>Recent administrative activity</v-card-title><v-card-text><v-alert v-if="!dashboard?.recentActivity?.length" type="info" variant="tonal">No administrative activity has been recorded.</v-alert><v-table v-else><thead><tr><th>Action</th><th>Target</th><th>When</th></tr></thead><tbody><tr v-for="entry in dashboard.recentActivity" :key="entry.id"><td>{{ entry.action }}</td><td>{{ entry.targetEntityType }} · {{ entry.targetEntityId }}</td><td>{{ formatDate(entry.timestampUtc) }}</td></tr></tbody></v-table></v-card-text></v-card>
      </v-window-item>
      <v-window-item value="users"><v-card rounded="lg"><v-card-title>Users</v-card-title><v-card-text><div class="d-flex ga-2 mb-4"><v-text-field v-model="userSearch" label="Search name or email" prepend-inner-icon="mdi-magnify" hide-details clearable @keyup.enter="loadUsers"/><v-btn @click="loadUsers">Search</v-btn></div><v-progress-linear v-if="busy" indeterminate/><v-table v-else><thead><tr><th>Name</th><th>Email</th><th>Account</th><th>Platform role</th><th>Lockout</th><th class="text-right">Actions</th></tr></thead><tbody><tr v-for="u in usersPage.items" :key="u.id"><td>{{ u.displayName || '—' }}</td><td>{{ u.email || '—' }}</td><td>{{ u.isActive ? 'Active' : 'Inactive' }}</td><td><v-chip size="small" :color="u.isSystemAdministrator ? 'deep-purple' : 'grey'">{{ u.isSystemAdministrator ? 'System Administrator' : 'User' }}</v-chip></td><td>{{ u.lockoutEnd ? formatDate(u.lockoutEnd) : '—' }}</td><td class="text-right"><v-btn size="small" variant="text" @click="viewUser(u.id)">Details</v-btn><v-btn size="small" variant="text" @click="setAdmin(u)">{{ u.isSystemAdministrator ? 'Revoke admin' : 'Make admin' }}</v-btn><v-btn size="small" variant="text" :color="u.isActive ? 'error' : 'success'" @click="setAccountActive(u)">{{ u.isActive ? 'Deactivate' : 'Reactivate' }}</v-btn></td></tr></tbody></v-table><PageButtons :page="usersPage.pageNumber" :page-size="usersPage.pageSize" :total="usersPage.totalCount" @change="loadUsers"/></v-card-text></v-card></v-window-item>
      <v-window-item value="organizers"><v-card rounded="lg"><v-card-title>Organizers</v-card-title><v-card-text><div class="d-flex ga-2 mb-4"><v-text-field v-model="organizerSearch" label="Search name or slug" prepend-inner-icon="mdi-magnify" hide-details clearable @keyup.enter="loadOrganizers"/><v-btn @click="loadOrganizers">Search</v-btn></div><v-progress-linear v-if="busy" indeterminate/><v-table v-else><thead><tr><th>Organizer</th><th>Status</th><th>Members</th><th>Events</th><th>Created</th><th class="text-right">Actions</th></tr></thead><tbody><tr v-for="o in organizersPage.items" :key="o.id"><td><strong>{{ o.name }}</strong><div class="text-caption text-medium-emphasis">{{ o.slug }}</div></td><td><v-chip size="small" :color="statusColor(o.status)">{{ o.status }}</v-chip></td><td>{{ o.memberCount }}</td><td>{{ o.eventCount }}</td><td>{{ formatDate(o.createdAt) }}</td><td class="text-right"><v-btn size="small" variant="text" @click="viewOrganizer(o.id)">Details</v-btn><v-btn size="small" variant="text" @click="viewOrganizerMembers(o.id)">Members</v-btn><v-btn size="small" variant="text" @click="viewOrganizerEvents(o.id)">Events</v-btn><v-menu><template #activator="{ props }"><v-btn v-bind="props" size="small" variant="text">Change status</v-btn></template><v-list density="compact"><v-list-item v-for="status in lifecycleStatuses" :key="status" :title="status" :disabled="status === o.status" @click="changeOrganizerStatus(o, status)"/></v-list></v-menu></td></tr></tbody></v-table><PageButtons :page="organizersPage.pageNumber" :page-size="organizersPage.pageSize" :total="organizersPage.totalCount" @change="loadOrganizers"/></v-card-text></v-card></v-window-item>
      <v-window-item value="audit"><v-card rounded="lg"><v-card-title>Administrative audit history</v-card-title><v-card-text><div class="d-flex flex-wrap ga-2 mb-4"><v-select v-model="auditOrganizer" :items="organizersPage.items" item-title="name" item-value="id" label="Scope" clearable hide-details style="max-width:260px"/><v-text-field v-model="auditAction" label="Action" hide-details style="max-width:180px"/><v-text-field v-model="auditSearch" label="Search actor or target" hide-details/><v-text-field v-model="auditFrom" type="date" label="From (UTC)" hide-details style="max-width:180px"/><v-text-field v-model="auditTo" type="date" label="To (UTC)" hide-details style="max-width:180px"/><v-btn @click="loadAudit">Filter</v-btn></div><v-progress-linear v-if="busy" indeterminate/><v-alert v-else-if="!auditPage.items.length" type="info" variant="tonal">No audit records match these filters.</v-alert><v-table v-else><thead><tr><th>Time (UTC)</th><th>Actor</th><th>Action</th><th>Target</th><th>Organizer</th><th>Metadata</th></tr></thead><tbody><tr v-for="record in auditPage.items" :key="record.id"><td>{{ formatEventTime(record.timestampUtc, 'UTC') }}</td><td>{{ record.actorIdentity || record.actorUserId || 'System' }}</td><td>{{ record.action }}</td><td>{{ record.targetEntityType }} · {{ record.targetEntityId }}</td><td>{{ record.organizerId || 'Platform' }}</td><td>{{ record.metadataJson || '—' }}</td></tr></tbody></v-table><PageButtons :page="auditPage.pageNumber" :page-size="auditPage.pageSize" :total="auditPage.totalCount" @change="loadAudit"/></v-card-text></v-card></v-window-item>
    </v-window>
    <v-dialog v-model="detailDialog" max-width="900"><v-card :title="detailTitle"><v-card-text><pre class="detail-json">{{ JSON.stringify(detail, null, 2) }}</pre></v-card-text><v-card-actions><v-spacer/><v-btn @click="detailDialog=false">Close</v-btn></v-card-actions></v-card></v-dialog>
    <v-dialog v-model="confirmDialog" max-width="460"><v-card :title="confirmTitle"><v-card-text>{{ confirmText }}</v-card-text><v-card-actions><v-spacer/><v-btn @click="confirmDialog=false">Cancel</v-btn><v-btn color="primary" :loading="saving" @click="confirmAction">Confirm</v-btn></v-card-actions></v-card></v-dialog>
    <v-snackbar v-model="snack" :color="snackColor" timeout="4000">{{ snackText }}</v-snackbar>
  </section>
</template>

<script setup lang="ts">
import { formatEventTime } from '../services/eventTime'
import { computed, defineComponent, h, onMounted, ref } from 'vue'
import { isAxiosError } from 'axios'
import { platformAdminApi, type AuditRecord, type Page, type PlatformOrganizer, type PlatformUser } from '../services/platformAdmin'

const PageButtons = defineComponent({ props: { page: { type: Number, required: true }, pageSize: { type: Number, required: true }, total: { type: Number, required: true } }, emits: ['change'], setup(props, { emit }) { return () => props.total > props.pageSize ? h('div', { class: 'd-flex justify-end align-center ga-2 mt-3' }, [`Page ${props.page} of ${Math.ceil(props.total / props.pageSize)}`, h('button', { class: 'v-btn v-btn--variant-text', disabled: props.page <= 1, onClick: () => emit('change', props.page - 1) }, 'Previous'), h('button', { class: 'v-btn v-btn--variant-text', disabled: props.page >= Math.ceil(props.total / props.pageSize), onClick: () => emit('change', props.page + 1) }, 'Next')]) : null } })
const tab = ref('overview'), activeRequests = ref(0), busy = computed(() => activeRequests.value > 0), saving = ref(false), error = ref('')
const dashboard = ref<any>(null)
const usersPage = ref<Page<PlatformUser>>({ items: [], pageNumber: 1, pageSize: 25, totalCount: 0 }), organizersPage = ref<Page<PlatformOrganizer>>({ items: [], pageNumber: 1, pageSize: 25, totalCount: 0 }), auditPage = ref<Page<AuditRecord>>({ items: [], pageNumber: 1, pageSize: 50, totalCount: 0 })
const userSearch = ref(''), organizerSearch = ref(''), auditOrganizer = ref(''), auditAction = ref(''), auditSearch = ref(''), auditFrom = ref(''), auditTo = ref('')
const detailDialog = ref(false), detailTitle = ref(''), detail = ref<unknown>(null), confirmDialog = ref(false), confirmTitle = ref(''), confirmText = ref(''), action = ref<(() => Promise<void>) | null>(null)
const snack = ref(false), snackText = ref(''), snackColor = ref('success')
const lifecycleStatuses = ['Active', 'Suspended', 'Inactive'] as const
const metrics = computed(() => dashboard.value ? [
  { label: 'Registered users', value: dashboard.value.registeredUsers }, { label: 'Platform administrators', value: dashboard.value.platformAdministrators },
  { label: 'Active organizers', value: dashboard.value.activeOrganizers }, { label: 'Suspended organizers', value: dashboard.value.suspendedOrganizers },
  { label: 'Inactive organizers', value: dashboard.value.inactiveOrganizers },
] : [])
onMounted(async () => { await loadDashboard(); await Promise.all([loadUsers(1), loadOrganizers(1), loadAudit(1)]) })
async function run<T>(fn: () => Promise<T>, success?: string) { activeRequests.value++; error.value = ''; try { const value = await fn(); if (success) notify(success); return value } catch (e) { error.value = err(e); return null } finally { activeRequests.value-- } }
async function loadDashboard() { await run(async () => { dashboard.value = (await platformAdminApi.dashboard()).data }) }
async function loadUsers(page = usersPage.value.pageNumber) { await run(async () => { usersPage.value = (await platformAdminApi.users({ search: userSearch.value || undefined, page, pageSize: 25 })).data }) }
async function loadOrganizers(page = organizersPage.value.pageNumber) { await run(async () => { organizersPage.value = (await platformAdminApi.organizers({ search: organizerSearch.value || undefined, page, pageSize: 25 })).data }) }
async function loadAudit(page = auditPage.value.pageNumber) { await run(async () => { const params = { action: auditAction.value || undefined, search: auditSearch.value || undefined, fromUtc: auditFrom.value ? `${auditFrom.value}T00:00:00Z` : undefined, toUtc: auditTo.value ? `${auditTo.value}T23:59:59Z` : undefined, page, pageSize: 50 }; auditPage.value = (auditOrganizer.value ? (await platformAdminApi.organizerAudit(auditOrganizer.value, params)).data : (await platformAdminApi.audit(params)).data) }) }
function confirm(title: string, message: string, fn: () => Promise<void>) { confirmTitle.value = title; confirmText.value = message; action.value = fn; confirmDialog.value = true }
function setAdmin(u: PlatformUser) { const next = !u.isSystemAdministrator; confirm(next ? 'Grant platform administrator' : 'Revoke platform administrator', `${next ? 'Grant' : 'Remove'} SystemAdministrator privileges for ${u.email}?`, async () => { await platformAdminApi.setPlatformAdmin(u.id, next); await Promise.all([loadUsers(), loadDashboard()]) }) }
function setAccountActive(u: PlatformUser) { const next = !u.isActive; confirm(next ? 'Reactivate account' : 'Deactivate account', `${next ? 'Reactivate' : 'Deactivate'} ${u.email}?`, async () => { await platformAdminApi.setUserStatus(u.id, next); await Promise.all([loadUsers(), loadDashboard()]) }) }
function changeOrganizerStatus(o: PlatformOrganizer, next: typeof lifecycleStatuses[number]) { confirm(`Set organizer ${next.toLowerCase()}`, `Set ${o.name} to ${next}? Its historical data will remain intact.`, async () => { await platformAdminApi.setOrganizerStatus(o.id, next); await Promise.all([loadOrganizers(), loadDashboard()]) }) }
async function confirmAction() { saving.value = true; try { await action.value?.(); confirmDialog.value = false; notify('Administrative change saved.') } catch (e) { error.value = err(e) } finally { saving.value = false } }
async function viewOrganizer(id: string) { const r = await run(async () => { const response = await platformAdminApi.organizerDetails(id); detail.value = response.data; detailTitle.value = 'Organizer details'; detailDialog.value = true }) }
async function viewUser(id: string) { await run(async () => { detail.value = (await platformAdminApi.userDetails(id)).data; detailTitle.value = 'User details'; detailDialog.value = true }) }
async function viewOrganizerMembers(id: string) { await run(async () => { detail.value = (await platformAdminApi.organizerMembers(id)).data; detailTitle.value = 'Organizer members'; detailDialog.value = true }) }
async function viewOrganizerEvents(id: string) { await run(async () => { detail.value = (await platformAdminApi.organizerEvents(id)).data; detailTitle.value = 'Organizer events'; detailDialog.value = true }) }
function formatDate(v: string) { return new Date(v).toLocaleString() }
function statusColor(s: string) { return s === 'Active' ? 'success' : s === 'Suspended' ? 'warning' : 'grey' }
function notify(message: string) { snackText.value = message; snackColor.value = 'success'; snack.value = true }
function err(e: unknown) {
  if (!isAxiosError(e)) return 'Request failed.'
  if (e.response?.status === 401) return 'Your session expired. Sign in again to continue.'
  if (e.response?.status === 403) return 'You do not have permission to perform this action.'
  return e.response?.data?.title || e.message
}
</script>

<style scoped>.detail-json { white-space: pre-wrap; overflow-wrap: anywhere; max-height: 65vh; overflow: auto; }</style>
